from solution import even_Power_Sum


def test_issue_example_n2():
    """Example: even_Power_Sum(2) == 1056."""
    assert even_Power_Sum(2) == 1056  # 2**5 + 4**5 = 32 + 1024 = 1056


def test_issue_first_one_even():
    """Sum of fifth power of first 1 even natural number."""
    assert even_Power_Sum(1) == 32  # 2**5 = 32


def test_issue_first_three_evens():
    """Sum of fifth powers of first 3 even natural numbers."""
    assert even_Power_Sum(3) == 8832  # 32 + 1024 + 7776 = 8832


def test_issue_first_four_evens():
    """Sum of fifth powers of first 4 even natural numbers."""
    assert even_Power_Sum(4) == 41600  # 32 + 1024 + 7776 + 32768 = 41600


def test_issue_first_five_evens():
    """Sum of fifth powers of first 5 even natural numbers."""
    assert even_Power_Sum(5) == 141600  # 41600 + 10**5 = 41600 + 100000 = 141600


def test_issue_first_six_evens():
    """Sum of fifth powers of first 6 even natural numbers."""
    assert even_Power_Sum(6) == 390432  # 141600 + 12**5 = 141600 + 248832 = 390432


def test_issue_first_ten_evens():
    """Sum of fifth powers of first 10 even natural numbers."""
    assert even_Power_Sum(10) == 7066400  # sum (2*i)**5 for i=1..10 = 7066400


def test_issue_empty_zero():
    """Sum of fifth powers of first 0 even natural numbers is empty sum."""
    assert even_Power_Sum(0) == 0  # sum of zero terms = 0


def test_contract_callable():
    """Public interface exposes callable even_Power_Sum."""
    assert callable(even_Power_Sum)


def test_contract_returns_int():
    """Sum of fifth powers of even naturals is an integer."""
    assert isinstance(even_Power_Sum(3), int)


def test_contract_successive_difference():
    """Sum for n minus sum for n-1 equals the next even fifth power."""
    assert even_Power_Sum(4) - even_Power_Sum(3) == 32768  # 8**5 = 32768
